"""Patch the platform folders generated by `flutter create .` with what PG Derma needs.
Run from flutter/ after `flutter create`. Safe to run more than once."""
import pathlib, re

root = pathlib.Path(__file__).resolve().parent.parent

# ---------- Android ----------
manifest = root / 'android/app/src/main/AndroidManifest.xml'
if manifest.exists():
    s = manifest.read_text()
    perms = ['android.permission.CAMERA', 'android.permission.RECORD_AUDIO', 'android.permission.USE_BIOMETRIC', 'android.permission.INTERNET']
    add = ''.join(f'    <uses-permission android:name="{p}"/>\n' for p in perms if p not in s)
    if add:
        s = s.replace('<application', add + '    <application', 1)
    if '<queries>' not in s:  # url_launcher (wa.me) + speech recognition visibility on Android 11+
        s = s.replace('</manifest>', '''    <queries>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="https"/></intent>
        <intent><action android:name="android.speech.RecognitionService"/></intent>
    </queries>
</manifest>''', 1)
    s = s.replace('android:label="pg_derma"', 'android:label="PG Derma"')
    manifest.write_text(s)

for gradle in [root / 'android/app/build.gradle.kts', root / 'android/app/build.gradle']:
    if gradle.exists():
        g = gradle.read_text()
        g = re.sub(r'minSdk\s*=\s*flutter\.minSdkVersion', 'minSdk = 24', g)
        g = re.sub(r'minSdkVersion\s+flutter\.minSdkVersion', 'minSdkVersion 24', g)
        gradle.write_text(g)

# R8: ML Kit text recognition references optional script packs (Chinese/Devanagari/Japanese/Korean)
# that we don't bundle. Flutter's Gradle plugin applies android/app/proguard-rules.pro to release builds.
(root / 'android/app/proguard-rules.pro').write_text("""-dontwarn com.google.mlkit.vision.text.chinese.**
-dontwarn com.google.mlkit.vision.text.devanagari.**
-dontwarn com.google.mlkit.vision.text.japanese.**
-dontwarn com.google.mlkit.vision.text.korean.**
-keep class com.google.mlkit.** { *; }
""")

# Android lint crashes analysing camera_android_camerax (a lint bug, not our code), which fails
# assembleRelease. Skip the release-time "lintVital" check in every module.
for rootgradle in [root / 'android/build.gradle.kts', root / 'android/build.gradle']:
    if rootgradle.exists():
        rg = rootgradle.read_text()
        if 'lintVital' not in rg:
            rg += '\nsubprojects {\n    tasks.matching { it.name.contains("lintVital") }.configureEach { enabled = false }\n}\n'
            rootgradle.write_text(rg)

# local_auth needs FlutterFragmentActivity
for act in root.glob('android/app/src/main/kotlin/**/MainActivity.kt'):
    a = act.read_text()
    a = a.replace('import io.flutter.embedding.android.FlutterActivity', 'import io.flutter.embedding.android.FlutterFragmentActivity')
    a = a.replace(': FlutterActivity()', ': FlutterFragmentActivity()')
    act.write_text(a)

# ---------- iOS ----------
plist = root / 'ios/Runner/Info.plist'
if plist.exists():
    p = plist.read_text()
    entries = {
        'NSCameraUsageDescription': 'Clinical photos are stored only in the encrypted in-app vault.',
        'NSFaceIDUsageDescription': 'Unlock your encrypted patient vault.',
        'NSMicrophoneUsageDescription': 'Voice-to-text for clinical notes.',
        'NSSpeechRecognitionUsageDescription': 'Voice-to-text for clinical notes.',
    }
    add = ''.join(f'\t<key>{k}</key>\n\t<string>{v}</string>\n' for k, v in entries.items() if k not in p)
    if add:
        p = p.replace('<dict>', '<dict>\n' + add, 1)
    p = p.replace('<string>Pg Derma</string>', '<string>PG Derma</string>')
    plist.write_text(p)

podfile = root / 'ios/Podfile'
if podfile.exists():
    pf = podfile.read_text()
    pf = re.sub(r"#?\s*platform :ios, '[\d.]+'", "platform :ios, '15.5'", pf)
    podfile.write_text(pf)

# the template's counter-app test does not apply to this app
wt = root / 'test/widget_test.dart'
if wt.exists() and 'MyApp' in wt.read_text():
    wt.unlink()
print('platform setup done')
